-- public.worker_gatherable(p_world uuid, p_x integer, p_y integer, p_kind text, c creature)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.worker_gatherable(p_world uuid, p_x integer, p_y integer, p_kind text, c creature)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
declare here int; t tile_def; rock rock_def; v_crop crop;
begin
  -- Never on another settlement, a citizen's or a stranger's (`private.worker_ground`).
  if c.keeper is not null and not private.worker_ground(p_world, c.keeper, p_x, p_y) then return false; end if;
  if p_kind = 'hive' then
    return in_bounds(p_world, p_x, p_y) and exists (select 1 from placed pl where pl.world_id = p_world and pl.kind = 'furniture'
      and pl.sub = 'hive' and pl.x = p_x and pl.y = p_y and pl.crumbles_at is null);
  end if;
  if not in_bounds(p_world, p_x, p_y) or claimed(p_world, p_x, p_y, c.id) then return false; end if;
  here := land_tile(p_world, p_x, p_y);
  select * into t from tile_def where id = here;

  if p_kind = 'bush' then
    if not creature_tile_ok(p_world, p_x, p_y) then return false; end if;
    -- A trellis with its vine ripe (`ripeTrellisAt`).
    if exists (select 1 from placed pl where pl.world_id = p_world and pl.kind = 'furniture' and pl.sub = vine_kind()
                 and pl.x = p_x and pl.y = p_y and vine_stage(pl, vine_now()) = 'ripe') then return true; end if;
    -- A bush in its season with nothing taken off it today.
    return here = tile_id('Bush') and not is_foraged(p_world, p_x, p_y, 'forage')
       and exists (select 1 from bush_def b where b.id = bush_species(land_data(p_world, p_x, p_y))
                    and b.yields is not null and fruits_now(b.yields));
  elsif p_kind = 'grass' then
    if not creature_tile_ok(p_world, p_x, p_y) then return false; end if;
    if here = tile_id('Moss') then return not is_foraged(p_world, p_x, p_y, 'moss'); end if;
    return here in (tile_id('Grass'), tile_id('Steppe'), tile_id('Lawn'), tile_id('Tundra'))
       and not is_foraged(p_world, p_x, p_y, 'grass');
  elsif p_kind = 'moss' then
    -- Moss grown back since its last cut, as your own hands cut it (`cut_moss`).
    return here = tile_id('Moss') and creature_tile_ok(p_world, p_x, p_y) and not is_foraged(p_world, p_x, p_y, 'moss');
  elsif p_kind = 'pan' then
    -- Sand with the water at one of its corners, as a person's pan wants.
    return here = tile_id('Sand') and creature_tile_ok(p_world, p_x, p_y)
       and exists (select 1 from tile_corners(p_x, p_y) k where land_height(p_world, k.cx, k.cy) < 0);
  end if;

  if p_kind = 'worm' then
    return coalesce(t.wormy, false) and not has_water(p_world, p_x, p_y) and creature_tile_ok(p_world, p_x, p_y)
       and not is_foraged(p_world, p_x, p_y, 'worm');
  elsif p_kind in ('sprout', 'resin') then
    if here <> tile_id('Tree') or not exists (select 1 from beside_tile(p_world, p_x, p_y)) then return false; end if;
    if p_kind = 'sprout' then
      return coalesce((select a.alive and a.logs > 0 from tree_age_def a where a.id = tree_age(land_data(p_world, p_x, p_y))), false)
         and not is_foraged(p_world, p_x, p_y, 'sprout');
    end if;
    return tree_species(land_data(p_world, p_x, p_y)) = resin_tree()
       and coalesce((select a.alive and a.logs > 0 from tree_age_def a where a.id = tree_age(land_data(p_world, p_x, p_y))), false)
       and not exists (select 1 from foraged f where f.world_id = p_world and f.x = p_x and f.y = p_y
                         and f.kind = 'resin' and f.at >= tree_last_dawn());
  elsif p_kind = 'flower' then
    -- In flower, and not where a skep gathers: its honey is the flowers in reach of it.
    return flowers_on(p_world, p_x, p_y, now()) > 0 and creature_tile_ok(p_world, p_x, p_y)
       and not exists (select 1 from placed pl where pl.world_id = p_world and pl.kind = 'furniture' and pl.sub in ('skep', 'hive')
                         and greatest(abs(pl.x - p_x), abs(pl.y - p_y)) <= skep_reach());
  elsif p_kind = 'scrub' then
    return creature_tile_ok(p_world, p_x, p_y) and green_on_tile(p_world, c.keeper, p_x, p_y) > 0;
  end if;

  if p_kind = 'woodcut' then
    return here = tile_id('Tree') and exists (select 1 from beside_tile(p_world, p_x, p_y));
  elsif p_kind = 'prune' then
    -- What would otherwise die: a stage that prunes back and whose next stage
    -- has no life in it. Nothing else is touched — a mature tree pruned stops
    -- bearing, and a sapling pruned is a shrub for good.
    return here = tile_id('Tree') and exists (select 1 from beside_tile(p_world, p_x, p_y))
       and exists (select 1 from tree_age_def a join tree_age_def n on n.id = a.next
                    where a.id = tree_age(land_data(p_world, p_x, p_y))
                      and a.pruned is not null and not n.alive);
  elsif p_kind = 'fruit' then
    -- A bearing tree with something on it, and a tile beside it to stand on.
    return here = tile_id('Tree') and exists (select 1 from beside_tile(p_world, p_x, p_y))
       and not is_foraged(p_world, p_x, p_y, 'forage')
       and exists (select 1 from tree_def td, tree_age_def a
                    where td.id = tree_species(land_data(p_world, p_x, p_y))
                      and a.id = tree_age(land_data(p_world, p_x, p_y))
                      and td.fruit is not null and a.bears and a.alive
                      -- Fruiting seasons: out of its season there is nothing to climb for (`fruiting.ts`).
                      and fruits_now(td.fruit));
  elsif p_kind = 'stump' then
    return here = tile_id('Stump') and creature_tile_ok(p_world, p_x, p_y);
  elsif p_kind = 'mine' then
    rock := bedrock_at(p_world, p_x, p_y);
    return here = tile_id('Rock') and rock.seam and rock.level <= task_skill(c)
       and rock_height(p_world, p_x, p_y) > -mine_depth() and face_reach(p_world, p_x, p_y);
  elsif p_kind = 'quarry' then
    rock := bedrock_at(p_world, p_x, p_y);
    return here in (tile_id('Rock'), tile_id('Snow')) and not rock.seam and rock_height(p_world, p_x, p_y) > -mine_depth()
       and face_reach(p_world, p_x, p_y);
  elsif p_kind in ('sand', 'clay') then
    -- Collected off the top, as the player's Collect: no timer on the bed.
    return here = tile_id(case p_kind when 'sand' then 'Sand' else 'Clay' end)
       and creature_tile_ok(p_world, p_x, p_y);
  elsif p_kind = 'peat' then
    return here in (tile_id('Peat'), tile_id('Tar')) and creature_tile_ok(p_world, p_x, p_y);
  elsif p_kind = 'reed' then
    return here = tile_id('Reed') and not is_foraged(p_world, p_x, p_y, 'reed');
  elsif p_kind = 'fish' then
    return fishable(p_world, p_x, p_y);
  elsif p_kind = 'seek' then
    -- Ground nobody has been over yet, which is the only ground worth a nose.
    return t.diggable and not has_water(p_world, p_x, p_y)
       and creature_tile_ok(p_world, p_x, p_y)
       and not is_foraged(p_world, p_x, p_y, 'dig');
  elsif p_kind = 'fetch' then
    return on_home_deed(p_world, c.keeper, p_x, p_y) and creature_tile_ok(p_world, p_x, p_y)
       and exists (select 1 from item i where i.world_id = p_world and i.holder = 'ground'
                     and i.gx = p_x and i.gy = p_y);
  elsif p_kind = 'compost' then
    -- A carcass, or anything knocked about past saving.
    return on_home_deed(p_world, c.keeper, p_x, p_y) and creature_tile_ok(p_world, p_x, p_y)
       and exists (select 1 from item i where i.world_id = p_world and i.holder = 'ground'
                     and i.gx = p_x and i.gy = p_y and (i.def = 'corpse' or i.dmg >= 40));
  elsif p_kind = 'farm' then
    -- Growth is brought up to date for the whole search before it starts, in
    -- `worker_settle`: once, rather than once for each tile looked at. And
    -- the crop is read once here rather than three times over below, since
    -- this is asked of every tile of the ground, and most have no crop at all.
    select * into v_crop from crop cr where cr.world_id = p_world and cr.x = p_x and cr.y = p_y;
    -- On a bed up a storey, only by the stairs.
    if found and coalesce(v_crop.level, 0) > 0 and not storey_reached(p_world, p_x, p_y, v_crop.level) then return false; end if;
    if found and (v_crop.stage >= crop_ripe() or not v_crop.tended_now) then return true; end if;
    /*
     * And a field with nothing in it, which was never work at all: the island
     * knew how to weed a crop and how to reap one and not how to sow one, so a
     * seavic walked over bare fields with seed sitting in the crate behind it.
     * Reported exactly so.
     */
    /*
     * And seed lying on a field that is already sown, which this tile has no
     * use for. Reported as "seavics also move seeds to storage if not using
     * them when working deed": a harvest leaves its seed in the furrow, the
     * next sowing takes one of them, and the rest sat there under the growing
     * crop where nobody could see, count or cook them. Picking them up is
     * work, so it is work here.
     */
    if v_crop.x is not null then
      return exists (select 1 from item i join crop_def sd on sd.seed = i.def
                      where i.world_id = p_world and i.holder = 'ground'
                        and i.gx = p_x and i.gy = p_y);
    end if;
    -- `here` is this tile's kind, read at the top.
    -- An empty field, or an empty open bed it reaches (`worker_bed`).
    return (here = tile_id('Field') or worker_bed(p_world, p_x, p_y) is not null) and (sow_seed(p_world, c, p_x, p_y)).id is not null;
  elsif p_kind = 'forage' then
    return coalesce(t.forage, false) and not is_foraged(p_world, p_x, p_y, 'forage')
       and creature_tile_ok(p_world, p_x, p_y);
  elsif p_kind = 'botanize' then
    return coalesce(t.botanize, false) and not is_foraged(p_world, p_x, p_y, 'botanize')
       and creature_tile_ok(p_world, p_x, p_y);
  end if;
  return false;
end $function$
